    if duration is not None:
        total = _micros(duration)
        if total <= 0:
            return []
        # 只保留 k*Interval < Duration（§5）
        last_k = -((-total) // step) - 1
        if last_k < first_k:
            return []
    if trigger.end is not None:
        # 重复产生的时刻同样受 EndBoundary 约束（§5）
        room = _micros(trigger.end - occurrence)
        if room < 0:
            return []
        cap = room // step
        if last_k is None or cap < last_k:
