        k += 1
        moment += one_step
    return runs


def _collect(task, after, limit, horizon_days):
    """收集 ``after`` 之后最早的 ``limit`` 次运行（升序、去重）。"""
    runs = []
    seen = set()
    threshold = None

    for trigger in task.triggers:
