    index = _week_index(day)
    last = _weeks_in_month(day)
    for week in wanted:
        target = last if week >= 5 else week
        if index == target:
            return True
    return False


def _day_matches(trigger, day):
    """``day`` 这一天是否是这个触发器的一个主出现日（不看时刻）。"""
    kind = trigger.type

    if kind == "daily":
        # §3.1：锚点是 StartBoundary 的日期
        interval = trigger.days_interval
        if interval <= 0:
            raise TaskDefError("range", "DaysInterval out of 1..365: %r" % (interval,))
        return (day - trigger.start.date()).days % interval == 0

    if kind == "weekly":
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        interval = trigger.weeks_interval
        if interval <= 0:
            raise TaskDefError("range", "WeeksInterval out of 1..52: %r" % (interval,))
        # §3.2：StartBoundary 所在周是第 0 周，之后每隔 interval 周
        return _week_number(day, trigger.start.date()) % interval == 0

    if kind == "monthly":
        # §3.3：月份与日号都要命中
        if trigger.months and day.month not in trigger.months:
            return False
        return day.day in trigger.days_of_month

    if kind == "monthly_dow":
        if trigger.months and day.month not in trigger.months:
            return False
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        return _match_week(day, trigger.weeks_of_month)

    if kind == "time":
        return day == trigger.start.date()

    raise TaskDefError("trigger", "unknown trigger type: %r" % (kind,))


# ------------------------------------------------------------------ 出现时刻


def _scan_bounds(trigger, after, horizon_days):
    """返回主出现日扫描区间 ``(first, last)``；无候选时返回 ``None``。"""
    start_day = trigger.start.date()
    last = max(after.date(), start_day) + timedelta(days=horizon_days)
    if trigger.end is not None and trigger.end.date() < last:
        last = trigger.end.date()
    if last < start_day:
        return None

    repetition = trigger.repetition
    if repetition is None or repetition.interval <= _ZERO:
        # 没有重复：早于 after 当日的主出现不可能产出 > after 的运行
        first = max(start_day, after.date())
    elif repetition.duration is not None:
        # 只有 ``T + Duration > after`` 的主出现才可能产出 after 之后的运行
        lookback = repetition.duration.days + 2
        first = max(start_day, after.date() - timedelta(days=lookback))
    else:
        # 不限时长的重复：任何主出现都可能一直延续到 after 之后
        first = start_day
    if first > last:
        return None
    return first, last


def _primary_occurrences(trigger, after, horizon_days=HORIZON_DAYS):
    """惰性产出主出现时刻（升序，可含早于 ``after`` 的，供重复展开使用）。"""
    bounds = _scan_bounds(trigger, after, horizon_days)
    if bounds is None:
        return
    first, last = bounds
    time_of_day = trigger.start.time()
    one_day = timedelta(days=1)
    day = first
    while day <= last:
        if _day_matches(trigger, day):
            moment = datetime.combine(day, time_of_day)
            # §4：主出现必须 >= StartBoundary，且不得超过 EndBoundary
            if moment >= trigger.start:
                if trigger.end is not None and moment > trigger.end:
                    return
                yield moment
        day += one_day


def _expand(trigger, occurrence, after, limit):
    """把一次主出现展开为若干次实际运行（含 ``<Repetition>``，见 §5）。"""
    if limit <= 0:
        return []
    repetition = trigger.repetition
    if repetition is None:
        return [occurrence] if occurrence > after else []

    step = _micros(repetition.interval)
    if step <= 0:
        # 退化配置：按「不重复」处理，避免除零与死循环。
        return [occurrence] if occurrence > after else []

    gap = _micros(after - occurrence)
    if gap < 0:
        first_k = 0
    else:
        # 最小的 k 使得 occurrence + k*Interval 严格晚于 after
        first_k = gap // step + 1

    last_k = None
    duration = repetition.duration
    if duration is not None:
        total = _micros(duration)
        if total <= 0:
            return []
        # §5：只保留 k*Interval < Duration
        last_k = -((-total) // step) - 1
        if last_k < first_k:
            return []
    if trigger.end is not None:
        # §5：重复产生的时刻同样受 EndBoundary 约束
        room = _micros(trigger.end - occurrence)
        if room < 0:
            return []
        cap = room // step
        if last_k is None or cap < last_k:
            last_k = cap
        if last_k < first_k:
            return []

    runs = []
    one_step = timedelta(microseconds=step)
    moment = occurrence + one_step * first_k
    k = first_k
    while len(runs) < limit and (last_k is None or k <= last_k):
        runs.append(moment)
        k += 1
        moment += one_step
    return runs


def _collect(task, after, limit, horizon_days):
    """收集 ``after`` 之后最早的 ``limit`` 次运行（升序、去重）。"""
    runs = []
    seen = set()
    threshold = None
    budget = _EXPANSION_BUDGET

    for trigger in task.triggers:
        # §8：单个触发器被禁用时跳过该触发器
        if not trigger.enabled:
            continue
        for occurrence in _primary_occurrences(trigger, after, horizon_days):
            # 主出现升序：一旦超过当前第 limit 名的时刻，后面的都无望入选
            if threshold is not None and occurrence > threshold:
                break
            if budget <= 0:
                break
            room = limit if limit < budget else budget
            expanded = _expand(trigger, occurrence, after, room)
            budget -= len(expanded)
            for moment in expanded:
                if moment not in seen:
                    seen.add(moment)
                    runs.append(moment)
            if len(runs) >= limit:
                runs.sort()
                del runs[limit:]
                threshold = runs[-1]

    runs.sort()
    return runs


# ------------------------------------------------------------------ 公共 API


def next_runs(task, after, count):
    """返回 ``after`` 之后最近的 ``count`` 次运行时刻（升序、去重）。

    * 任务被禁用（``task.enabled`` 为假）时返回空列表；
    * 触发器被禁用（``trigger.enabled`` 为假）时跳过该触发器；
    * 返回的时刻**严格大于** ``after``；不足 ``count`` 次时返回实际数量。
    """
    if not task.enabled:
        return []
    if count is None or count <= 0:
        return []
    return _collect(task, after, int(count), HORIZON_DAYS)


def plan_window(task, start, end):
    """返回位于 ``(start, end]`` 区间内的全部运行时刻（升序、去重）。"""
    if not task.enabled:
        return []
    if end < start:
        return []
    span = (end - start).days + 2
    horizon = span if span > HORIZON_DAYS else HORIZON_DAYS
    return [m for m in _collect(task, start, PLAN_HARD_LIMIT, horizon) if m <= end]


def validate_task(task):
    """跨字段一致性校验；不一致时抛 ``TaskDefError``。"""
    triggers = tuple(task.triggers or ())
    if not triggers:
        raise TaskDefError("structure", "task has no triggers")

    for trigger in triggers:
        if trigger.type not in TRIGGER_TYPES:
            raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))
        if trigger.end is not None and trigger.end < trigger.start:
            raise TaskDefError(
                "structure",
                "EndBoundary %s is earlier than StartBoundary %s"
                % (trigger.end.isoformat(), trigger.start.isoformat()),
            )

        if trigger.type == "daily" and not 1 <= trigger.days_interval <= 365:
            raise TaskDefError(
                "range", "DaysInterval out of 1..365: %r" % (trigger.days_interval,)
            )
        if trigger.type == "weekly" and not 1 <= trigger.weeks_interval <= 52:
            raise TaskDefError(
                "range", "WeeksInterval out of 1..52: %r" % (trigger.weeks_interval,)
            )
        for value in trigger.days_of_month:
            if not 1 <= value <= 31:
                raise TaskDefError("range", "Day out of 1..31: %r" % (value,))
        for value in trigger.weeks_of_month:
            if not 1 <= value <= 5:
                raise TaskDefError("range", "Week out of 1..5: %r" % (value,))
        for value in trigger.months:
            if not 1 <= value <= 12:
                raise TaskDefError("range", "month out of 1..12: %r" % (value,))
        for value in trigger.days_of_week:
            if not 0 <= value <= 6:
                raise TaskDefError("range", "weekday out of 0..6: %r" % (value,))

        repetition = trigger.repetition
        if repetition is not None:
            if repetition.interval <= _ZERO:
                raise TaskDefError("range", "repetition <Interval> must be positive")
            if repetition.duration is not None and repetition.duration <= _ZERO:
                raise TaskDefError("range", "repetition <Duration> must be positive")

    if task.execution_time_limit is not None and task.execution_time_limit < _ZERO:
        raise TaskDefError("range", "ExecutionTimeLimit must not be negative")
    if task.random_delay is not None and task.random_delay < _ZERO:
        raise TaskDefError("range", "RandomDelay must not be negative")
    return task

"""wtask.xmlio —— 任务 XML 的解析与规范化序列化。

语义依据 ``docs/TASKSCHEMA.md`` §1 / §2 / §6 / §7 / §9。
"""

import xml.etree.ElementTree as ET
from datetime import timedelta

from .duration import format_duration, parse_duration
from .errors import TaskDefError
from .model import MONTH_NAMES, WEEKDAY_NAMES, Repetition, Task, Trigger
from .schedule import validate_task

#: 受支持的 ``version`` 属性
SUPPORTED_VERSIONS = ("1.0", "1.2")

#: 默认命名空间（序列化时写回）
NS = "http://schemas.microsoft.com/windows/2004/02/mit/task"

DATETIME_FORMAT = "%Y-%m-%dT%H:%M:%S"

_DEFAULT_MULTIPLE_INSTANCES = "IgnoreNew"

_TRIGGER_TAGS = ("CalendarTrigger", "TimeTrigger")
_SCHEDULE_TAGS = (
    "ScheduleByDay",
    "ScheduleByWeek",
    "ScheduleByMonth",
    "ScheduleByMonthDayOfWeek",
)
_COMMON_TRIGGER_CHILDREN = ("StartBoundary", "EndBoundary", "Enabled", "Repetition")
_CALENDAR_ALLOWED = _COMMON_TRIGGER_CHILDREN + _SCHEDULE_TAGS
_TIME_ALLOWED = _COMMON_TRIGGER_CHILDREN
_REPETITION_ALLOWED = ("Interval", "Duration", "StopAtDurationEnd")

_DAYS_INTERVAL_RANGE = (1, 365)
_WEEKS_INTERVAL_RANGE = (1, 52)
_DAY_OF_MONTH_RANGE = (1, 31)
_WEEK_OF_MONTH_RANGE = (1, 5)


# ------------------------------------------------------------------ 解析工具


def _tag(element):
    """去掉命名空间前缀，返回本地标签名。"""
    tag = element.tag
    if not isinstance(tag, str):  # 注释 / 处理指令
        return ""
    return tag.split("}", 1)[1] if "}" in tag else tag


def _children(element, name):
    return [child for child in element if _tag(child) == name]


def _one(element, name):
    found = _children(element, name)
    if len(found) > 1:
        raise TaskDefError("schema", "duplicate <%s>" % name)
    return found[0] if found else None


def _text(element, name, required=False):
    child = _one(element, name)
    if child is None:
        if required:
            raise TaskDefError("schema", "missing required <%s>" % name)
        return None
    return (child.text or "").strip()


def _parse_datetime(text, name):
    from datetime import datetime

    try:
        return datetime.strptime((text or "").strip(), DATETIME_FORMAT)
    except (TypeError, ValueError):
        raise TaskDefError("range", "invalid datetime in <%s>: %r" % (name, text))


def _parse_bool(text, name):
    value = (text or "").strip().lower()
    if value in ("true", "1"):
        return True
    if value in ("false", "0"):
        return False
    raise TaskDefError("range", "invalid boolean in <%s>: %r" % (name, text))


def _parse_int(text, name):
    try:
        return int((text or "").strip())
    except (TypeError, ValueError):
        raise TaskDefError("range", "invalid integer in <%s>: %r" % (name, text))


def _parse_bounded_int(text, name, low, high):
    value = _parse_int(text, name)
    if not low <= value <= high:
        raise TaskDefError("range", "<%s> %d out of %d..%d" % (name, value, low, high))
    return value


def _check_children(element, allowed, where):
    for child in element:
        local = _tag(child)
        if not local:
            continue
        if local not in allowed:
            raise TaskDefError(
                "trigger", "unexpected <%s> inside <%s>" % (local, where)
            )


def _parse_weekdays(element, name):
    """解析 ``<DaysOfWeek><Monday/>…</DaysOfWeek>``；缺失时返回 ``None``。"""
    holder = _one(element, name)
    if holder is None:
        return None
    days = []
    for child in holder:
        local = _tag(child)
        if not local:
            continue
        if local not in WEEKDAY_NAMES:
            raise TaskDefError("trigger", "unknown weekday <%s> in <%s>" % (local, name))
        days.append(WEEKDAY_NAMES.index(local))
    if not days:
        raise TaskDefError("trigger", "<%s> is empty" % name)
    if len(set(days)) != len(days):
        raise TaskDefError("trigger", "duplicate weekday in <%s>" % name)
    # 规范化顺序：Sunday, Monday, … , Saturday
    return tuple(sorted(days))


def _parse_months(element):
    holder = _one(element, "Months")
    if holder is None:
        raise TaskDefError("schema", "missing required <Months>")
    months = []
    for child in holder:
        local = _tag(child)
        if not local:
            continue
        if local not in MONTH_NAMES:
            raise TaskDefError("trigger", "unknown month <%s> in <Months>" % local)
        months.append(MONTH_NAMES.index(local) + 1)
    if not months:
        raise TaskDefError("trigger", "<Months> is empty")
    if len(set(months)) != len(months):
        raise TaskDefError("trigger", "duplicate month in <Months>")
    # 规范化顺序：January … December
    return tuple(sorted(months))


def _parse_numbered_holder(schedule, holder_name, item_name, low, high):
    """解析 ``<DaysOfMonth><Day>1</Day>…</DaysOfMonth>`` 一类的容器。"""
    holder = _one(schedule, holder_name)
    if holder is None:
        raise TaskDefError("schema", "missing required <%s>" % holder_name)
    values = []
    for child in holder:
        local = _tag(child)
        if not local:
            continue
        if local != item_name:
            raise TaskDefError(
                "trigger", "unexpected <%s> inside <%s>" % (local, holder_name)
            )
        values.append(_parse_bounded_int(child.text, item_name, low, high))
    if not values:
        raise TaskDefError("trigger", "<%s> is empty" % holder_name)
    return tuple(sorted(set(values)))


def _parse_repetition(holder):
    element = _one(holder, "Repetition")
    if element is None:
        return None
    _check_children(element, _REPETITION_ALLOWED, "Repetition")

    interval_text = _text(element, "Interval", required=True)
    interval = parse_duration(interval_text)
    if interval <= timedelta(0):
        raise TaskDefError("range", "repetition <Interval> must be positive")

    duration_text = _text(element, "Duration")
    duration = parse_duration(duration_text) if duration_text is not None else None
    if duration is not None and duration <= timedelta(0):
        raise TaskDefError("range", "repetition <Duration> must be positive")

    stop_text = _text(element, "StopAtDurationEnd")
    stop = _parse_bool(stop_text, "StopAtDurationEnd") if stop_text is not None else False
    return Repetition(interval=interval, duration=duration, stop_at_duration_end=stop)


def _parse_common(element, where):
    """解析触发器公共部分：StartBoundary / EndBoundary / Enabled / Repetition。"""
    start = _parse_datetime(_text(element, "StartBoundary", required=True), "StartBoundary")
    end_text = _text(element, "EndBoundary")
    end = _parse_datetime(end_text, "EndBoundary") if end_text is not None else None
    enabled_text = _text(element, "Enabled")
    enabled = _parse_bool(enabled_text, "Enabled") if enabled_text is not None else True
    repetition = _parse_repetition(element)
    return start, end, enabled, repetition


def _parse_calendar(element):
    _check_children(element, _CALENDAR_ALLOWED, "CalendarTrigger")

    schedules = [child for child in element if _tag(child) in _SCHEDULE_TAGS]
    if not schedules:
        raise TaskDefError("trigger", "<CalendarTrigger> requires exactly one schedule")
    if len(schedules) > 1:
        raise TaskDefError(
            "trigger", "<CalendarTrigger> has %d schedules, expected 1" % len(schedules)
        )
    schedule = schedules[0]
    kind = _tag(schedule)

    start, end, enabled, repetition = _parse_common(element, "CalendarTrigger")

    if kind == "ScheduleByDay":
        _check_children(schedule, ("DaysInterval",), "ScheduleByDay")
        interval_text = _text(schedule, "DaysInterval")
        days_interval = (
            1
            if interval_text is None
            else _parse_bounded_int(
                interval_text, "DaysInterval", *_DAYS_INTERVAL_RANGE
            )
        )
        return Trigger(
            type="daily", start=start, end=end, enabled=enabled,
            days_interval=days_interval, repetition=repetition,
        )

    if kind == "ScheduleByWeek":
        _check_children(schedule, ("DaysOfWeek", "WeeksInterval"), "ScheduleByWeek")
        days_of_week = _parse_weekdays(schedule, "DaysOfWeek")
        if days_of_week is None:
            raise TaskDefError("trigger", "<ScheduleByWeek> requires <DaysOfWeek>")
        weeks_text = _text(schedule, "WeeksInterval")
        weeks_interval = (
            1
            if weeks_text is None
            else _parse_bounded_int(
                weeks_text, "WeeksInterval", *_WEEKS_INTERVAL_RANGE
            )
        )
        return Trigger(
            type="weekly", start=start, end=end, enabled=enabled,
            weeks_interval=weeks_interval, days_of_week=days_of_week,
            repetition=repetition,
        )

    if kind == "ScheduleByMonth":
        _check_children(schedule, ("DaysOfMonth", "Months"), "ScheduleByMonth")
        days_of_month = _parse_numbered_holder(
            schedule, "DaysOfMonth", "Day", *_DAY_OF_MONTH_RANGE
        )
        return Trigger(
            type="monthly", start=start, end=end, enabled=enabled,
            days_of_month=days_of_month, months=_parse_months(schedule),
            repetition=repetition,
        )

    # ScheduleByMonthDayOfWeek
    _check_children(
        schedule, ("Weeks", "DaysOfWeek", "Months"), "ScheduleByMonthDayOfWeek"
    )
    weeks_of_month = _parse_numbered_holder(
        schedule, "Weeks", "Week", *_WEEK_OF_MONTH_RANGE
    )
    days_of_week = _parse_weekdays(schedule, "DaysOfWeek")
    if days_of_week is None:
        raise TaskDefError("trigger", "<ScheduleByMonthDayOfWeek> requires <DaysOfWeek>")
    return Trigger(
        type="monthly_dow", start=start, end=end, enabled=enabled,
        days_of_week=days_of_week, weeks_of_month=weeks_of_month,
        months=_parse_months(schedule), repetition=repetition,
    )


def _parse_time(element):
    _check_children(element, _TIME_ALLOWED, "TimeTrigger")
    start, end, enabled, repetition = _parse_common(element, "TimeTrigger")
    return Trigger(
        type="time", start=start, end=end, enabled=enabled, repetition=repetition,
    )


def _parse_settings(root, fields):
    settings = _one(root, "Settings")
    if settings is None:
        return

    policy = _text(settings, "MultipleInstancesPolicy")
    if policy:
        fields["multiple_instances"] = policy

    enabled_text = _text(settings, "Enabled")
    if enabled_text is not None:
        fields["enabled"] = _parse_bool(enabled_text, "Enabled")

    limit_text = _text(settings, "ExecutionTimeLimit")
    if limit_text is not None:
        limit = parse_duration(limit_text)
        # §1：``PT0S`` 等于「不限」，模型里用 ``None`` 表示
        fields["execution_time_limit"] = limit if limit > timedelta(0) else None

    delay_text = _text(settings, "RandomDelay")
    if delay_text is not None:
        fields["random_delay"] = parse_duration(delay_text)


# ------------------------------------------------------------------ 公共 API


def parse_task_xml(text):
    """把任务 XML 解析为 :class:`~wtask.model.Task`。

    所有结构 / 取值问题都抛 :class:`~wtask.errors.TaskDefError`，
    ``kind`` 取值见 ``docs/TASKSCHEMA.md`` §9。
    """
    if not isinstance(text, (str, bytes)):
        raise TaskDefError("xml", "task xml must be str or bytes, got %r" % (type(text),))
    try:
        root = ET.fromstring(text)
    except ET.ParseError as exc:
        raise TaskDefError("xml", str(exc))
    except (ValueError, TypeError) as exc:  # 例如含 NUL 字符的文本
        raise TaskDefError("xml", str(exc))
    if root is None or not isinstance(root.tag, str):
        raise TaskDefError("xml", "task xml has no root element")

    if _tag(root) != "Task":
        raise TaskDefError("schema", "root element must be <Task>, got <%s>" % _tag(root))

    version = (root.get("version") or "").strip()
    if version not in SUPPORTED_VERSIONS:
        raise TaskDefError(
            "version", "unsupported task version: %r" % (root.get("version"),)
        )

    holders = _children(root, "Triggers")
    if not holders:
        raise TaskDefError("structure", "missing <Triggers>")
    if len(holders) > 1:
        raise TaskDefError("schema", "duplicate <Triggers>")

    triggers = []
    for child in holders[0]:
        local = _tag(child)
        if not local:
            continue
        if local == "CalendarTrigger":
            triggers.append(_parse_calendar(child))
        elif local == "TimeTrigger":
            triggers.append(_parse_time(child))
        else:
            # §2：``<Triggers>`` 下只允许 CalendarTrigger / TimeTrigger
            raise TaskDefError("trigger", "unknown trigger element <%s>" % local)
    if not triggers:
        raise TaskDefError("structure", "<Triggers> is empty")

    fields = {"version": version, "triggers": tuple(triggers)}
    _parse_settings(root, fields)

    task = Task(**fields)
    validate_task(task)
    return task


def _format_datetime(value):
    return value.strftime(DATETIME_FORMAT)


def _weekday_elements(days):
    return "".join("<%s/>" % WEEKDAY_NAMES[day] for day in sorted(days))


def _month_elements(months):
    return "".join("<%s/>" % MONTH_NAMES[month - 1] for month in sorted(months))


def _schedule_xml(trigger, inner):
    lines = []
    if trigger.type == "daily":
        lines.append(inner + "<ScheduleByDay>")
        lines.append(inner + "  <DaysInterval>%d</DaysInterval>" % trigger.days_interval)
        lines.append(inner + "</ScheduleByDay>")
    elif trigger.type == "weekly":
        lines.append(inner + "<ScheduleByWeek>")
        lines.append(
            inner + "  <DaysOfWeek>" + _weekday_elements(trigger.days_of_week) + "</DaysOfWeek>"
        )
        lines.append(inner + "  <WeeksInterval>%d</WeeksInterval>" % trigger.weeks_interval)
        lines.append(inner + "</ScheduleByWeek>")
    elif trigger.type == "monthly":
        lines.append(inner + "<ScheduleByMonth>")
        lines.append(
            inner
            + "  <DaysOfMonth>"
            + "".join("<Day>%d</Day>" % day for day in sorted(set(trigger.days_of_month)))
            + "</DaysOfMonth>"
        )
        lines.append(inner + "  <Months>" + _month_elements(trigger.months) + "</Months>")
        lines.append(inner + "</ScheduleByMonth>")
    elif trigger.type == "monthly_dow":
        lines.append(inner + "<ScheduleByMonthDayOfWeek>")
        lines.append(
            inner
            + "  <Weeks>"
            + "".join("<Week>%d</Week>" % week for week in sorted(set(trigger.weeks_of_month)))
            + "</Weeks>"
        )
        lines.append(
            inner + "  <DaysOfWeek>" + _weekday_elements(trigger.days_of_week) + "</DaysOfWeek>"
        )
        lines.append(inner + "  <Months>" + _month_elements(trigger.months) + "</Months>")
        lines.append(inner + "</ScheduleByMonthDayOfWeek>")
    elif trigger.type != "time":
        raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))
    return lines


def _trigger_xml(trigger, indent):
    pad = " " * indent
    inner = " " * (indent + 2)
    name = "TimeTrigger" if trigger.type == "time" else "CalendarTrigger"
    # 顺序固定：StartBoundary → EndBoundary → Enabled → 日程 → Repetition（§7）
    lines = [pad + "<%s>" % name]
    lines.append(inner + "<StartBoundary>%s</StartBoundary>" % _format_datetime(trigger.start))
    if trigger.end is not None:
        lines.append(inner + "<EndBoundary>%s</EndBoundary>" % _format_datetime(trigger.end))
    if not trigger.enabled:
        lines.append(inner + "<Enabled>false</Enabled>")

    lines.extend(_schedule_xml(trigger, inner))

    repetition = trigger.repetition
    if repetition is not None:
        lines.append(inner + "<Repetition>")
        lines.append(inner + "  <Interval>%s</Interval>" % format_duration(repetition.interval))
        if repetition.duration is not None:
            lines.append(
                inner + "  <Duration>%s</Duration>" % format_duration(repetition.duration)
            )
        if repetition.stop_at_duration_end:
            lines.append(inner + "  <StopAtDurationEnd>true</StopAtDurationEnd>")
        lines.append(inner + "</Repetition>")

    lines.append(pad + "</%s>" % name)
    return lines


def task_to_xml(task):
    """把 :class:`~wtask.model.Task` 规范化为 XML 文本。

    规范化规则见 ``docs/TASKSCHEMA.md`` §7：元素与属性顺序固定、缺省值省略、
    日期时间写作 ``YYYY-MM-DDTHH:MM:SS``、时长写成规范形式。
    """
    lines = ['<Task version="%s" xmlns="%s">' % (task.version, NS)]
    lines.append("  <Triggers>")
    for trigger in task.triggers:
        lines.extend(_trigger_xml(trigger, 4))
    lines.append("  </Triggers>")
    lines.append("  <Settings>")
    lines.append(
        "    <MultipleInstancesPolicy>%s</MultipleInstancesPolicy>" % task.multiple_instances
    )
    if not task.enabled:
        lines.append("    <Enabled>false</Enabled>")
    if task.execution_time_limit:
        lines.append(
            "    <ExecutionTimeLimit>%s</ExecutionTimeLimit>"
            % format_duration(task.execution_time_limit)
        )
    if task.random_delay:
        lines.append("    <RandomDelay>%s</RandomDelay>" % format_duration(task.random_delay))
    lines.append("  </Settings>")
    lines.append("</Task>")
    return "\n".join(lines) + "\n"

"""wtask.xmlio —— 任务 XML 的解析与规范化序列化。

语义依据 ``docs/TASKSCHEMA.md`` §1 / §2 / §6 / §7 / §9。
"""

import xml.etree.ElementTree as ET
from datetime import datetime, timedelta

from .duration import format_duration, parse_duration
from .errors import TaskDefError
from .model import MONTH_NAMES, WEEKDAY_NAMES, Repetition, Task, Trigger
from .schedule import validate_task

#: 受支持的 ``version`` 属性
SUPPORTED_VERSIONS = ("1.0", "1.2")

#: 默认命名空间（序列化时写回）
NS = "http://schemas.microsoft.com/windows/2004/02/mit/task"

DATETIME_FORMAT = "%Y-%m-%dT%H:%M:%S"

_DEFAULT_MULTIPLE_INSTANCES = "IgnoreNew"

_TRIGGER_TAGS = ("CalendarTrigger", "TimeTrigger")
_SCHEDULE_TAGS = (
    "ScheduleByDay",
    "ScheduleByWeek",
    "ScheduleByMonth",
    "ScheduleByMonthDayOfWeek",
)
_COMMON_TRIGGER_CHILDREN = ("StartBoundary", "EndBoundary", "Enabled", "Repetition")
_CALENDAR_ALLOWED = _COMMON_TRIGGER_CHILDREN + _SCHEDULE_TAGS
_TIME_ALLOWED = _COMMON_TRIGGER_CHILDREN
_REPETITION_ALLOWED = ("Interval", "Duration", "StopAtDurationEnd")

_DAYS_INTERVAL_RANGE = (1, 365)
_WEEKS_INTERVAL_RANGE = (1, 52)
_DAY_OF_MONTH_RANGE = (1, 31)
_WEEK_OF_MONTH_RANGE = (1, 5)


# ------------------------------------------------------------------ 解析工具


def _tag(element):
    """去掉命名空间前缀，返回本地标签名。"""
    tag = element.tag
    if not isinstance(tag, str):  # 注释 / 处理指令
        return ""
    return tag.split("}", 1)[1] if "}" in tag else tag


def _children(element, name):
    return [child for child in element if _tag(child) == name]


def _one(element, name):
    found = _children(element, name)
    if len(found) > 1:
        raise TaskDefError("schema", "duplicate <%s>" % name)
    return found[0] if found else None


def _text(element, name, required=False):
    child = _one(element, name)
    if child is None:
        if required:
            raise TaskDefError("schema", "missing required <%s>" % name)
        return None
    return (child.text or "").strip()


def _parse_datetime(text, name):
    try:
        return datetime.strptime((text or "").strip(), DATETIME_FORMAT)
    except (TypeError, ValueError):
        raise TaskDefError("range", "invalid datetime in <%s>: %r" % (name, text))


def _parse_bool(text, name):
    value = (text or "").strip().lower()
    if value in ("true", "1"):
        return True
    if value in ("false", "0"):
        return False
    raise TaskDefError("range", "invalid boolean in <%s>: %r" % (name, text))


def _parse_int(text, name):
    try:
        return int((text or "").strip())
    except (TypeError, ValueError):
        raise TaskDefError("range", "invalid integer in <%s>: %r" % (name, text))


def _parse_bounded_int(text, name, low, high):
    value = _parse_int(text, name)
    if not low <= value <= high:
        raise TaskDefError("range", "<%s> %d out of %d..%d" % (name, value, low, high))
    return value


def _check_children(element, allowed, where):
    for child in element:
        local = _tag(child)
        if not local:
            continue
        if local not in allowed:
            raise TaskDefError("trigger", "unexpected <%s> inside <%s>" % (local, where))


def _parse_weekdays(element, name):
    """解析 ``<DaysOfWeek><Monday/>…</DaysOfWeek>``；缺失时返回 ``None``。"""
    holder = _one(element, name)
    if holder is None:
        return None
    days = []
    for child in holder:
        local = _tag(child)
        if not local:
            continue
        if local not in WEEKDAY_NAMES:
            raise TaskDefError("trigger", "unknown weekday <%s> in <%s>" % (local, name))
        days.append(WEEKDAY_NAMES.index(local))
    if not days:
        raise TaskDefError("trigger", "<%s> is empty" % name)
    if len(set(days)) != len(days):
        raise TaskDefError("trigger", "duplicate weekday in <%s>" % name)
    # 规范化顺序：Sunday, Monday, … , Saturday
    return tuple(sorted(days))


def _parse_months(element):
    holder = _one(element, "Months")
    if holder is None:
        raise TaskDefError("schema", "missing required <Months>")
    months = []
    for child in holder:
        local = _tag(child)
        if not local:
            continue
        if local not in MONTH_NAMES:
            raise TaskDefError("trigger", "unknown month <%s> in <Months>" % local)
        months.append(MONTH_NAMES.index(local) + 1)
    if not months:
        raise TaskDefError("trigger", "<Months> is empty")
    if len(set(months)) != len(months):
        raise TaskDefError("trigger", "duplicate month in <Months>")
    # 规范化顺序：January … December
    return tuple(sorted(months))


def _parse_numbered_holder(schedule, holder_name, item_name, low, high):
    """解析 ``<DaysOfMonth><Day>1</Day>…</DaysOfMonth>`` 一类的容器。"""
    holder = _one(schedule, holder_name)
    if holder is None:
        raise TaskDefError("schema", "missing required <%s>" % holder_name)
    values = []
    for child in holder:
        local = _tag(child)
        if not local:
            continue
        if local != item_name:
            raise TaskDefError(
                "trigger", "unexpected <%s> inside <%s>" % (local, holder_name)
            )
        values.append(_parse_bounded_int(child.text, item_name, low, high))
    if not values:
        raise TaskDefError("trigger", "<%s> is empty" % holder_name)
    return tuple(sorted(set(values)))


def _parse_repetition(holder):
    element = _one(holder, "Repetition")
    if element is None:
        return None
    _check_children(element, _REPETITION_ALLOWED, "Repetition")

    interval_text = _text(element, "Interval", required=True)
    interval = parse_duration(interval_text)
    if interval <= timedelta(0):
        raise TaskDefError("range", "repetition <Interval> must be positive")

    duration_text = _text(element, "Duration")
    duration = parse_duration(duration_text) if duration_text is not None else None
    if duration is not None and duration <= timedelta(0):
        raise TaskDefError("range", "repetition <Duration> must be positive")

    stop_text = _text(element, "StopAtDurationEnd")
    stop = _parse_bool(stop_text, "StopAtDurationEnd") if stop_text is not None else False
    return Repetition(interval=interval, duration=duration, stop_at_duration_end=stop)


def _parse_common(element):
    """解析触发器公共部分：StartBoundary / EndBoundary / Enabled / Repetition。"""
    start = _parse_datetime(_text(element, "StartBoundary", required=True), "StartBoundary")
    end_text = _text(element, "EndBoundary")
    end = _parse_datetime(end_text, "EndBoundary") if end_text is not None else None
    enabled_text = _text(element, "Enabled")
    enabled = _parse_bool(enabled_text, "Enabled") if enabled_text is not None else True
    repetition = _parse_repetition(element)
    return start, end, enabled, repetition


def _parse_calendar(element):
    _check_children(element, _CALENDAR_ALLOWED, "CalendarTrigger")

    schedules = [child for child in element if _tag(child) in _SCHEDULE_TAGS]
    if not schedules:
        raise TaskDefError("trigger", "<CalendarTrigger> requires exactly one schedule")
    if len(schedules) > 1:
        raise TaskDefError(
            "trigger", "<CalendarTrigger> has %d schedules, expected 1" % len(schedules)
        )
    schedule = schedules[0]
    kind = _tag(schedule)

    start, end, enabled, repetition = _parse_common(element)

    if kind == "ScheduleByDay":
        _check_children(schedule, ("DaysInterval",), "ScheduleByDay")
        interval_text = _text(schedule, "DaysInterval")
        days_interval = (
            1
            if interval_text is None
            else _parse_bounded_int(interval_text, "DaysInterval", *_DAYS_INTERVAL_RANGE)
        )
        return Trigger(
            type="daily", start=start, end=end, enabled=enabled,
            days_interval=days_interval, repetition=repetition,
        )

    if kind == "ScheduleByWeek":
        _check_children(schedule, ("DaysOfWeek", "WeeksInterval"), "ScheduleByWeek")
        days_of_week = _parse_weekdays(schedule, "DaysOfWeek")
        if days_of_week is None:
            raise TaskDefError("trigger", "<ScheduleByWeek> requires <DaysOfWeek>")
        weeks_text = _text(schedule, "WeeksInterval")
        weeks_interval = (
            1
            if weeks_text is None
            else _parse_bounded_int(weeks_text, "WeeksInterval", *_WEEKS_INTERVAL_RANGE)
        )
        return Trigger(
            type="weekly", start=start, end=end, enabled=enabled,
            weeks_interval=weeks_interval, days_of_week=days_of_week,
            repetition=repetition,
        )

    if kind == "ScheduleByMonth":
        _check_children(schedule, ("DaysOfMonth", "Months"), "ScheduleByMonth")
        days_of_month = _parse_numbered_holder(
            schedule, "DaysOfMonth", "Day", *_DAY_OF_MONTH_RANGE
        )
        return Trigger(
            type="monthly", start=start, end=end, enabled=enabled,
            days_of_month=days_of_month, months=_parse_months(schedule),
            repetition=repetition,
        )

    # ScheduleByMonthDayOfWeek
    _check_children(schedule, ("Weeks", "DaysOfWeek", "Months"), "ScheduleByMonthDayOfWeek")
    weeks_of_month = _parse_numbered_holder(
        schedule, "Weeks", "Week", *_WEEK_OF_MONTH_RANGE
    )
    days_of_week = _parse_weekdays(schedule, "DaysOfWeek")
    if days_of_week is None:
        raise TaskDefError("trigger", "<ScheduleByMonthDayOfWeek> requires <DaysOfWeek>")
    return Trigger(
        type="monthly_dow", start=start, end=end, enabled=enabled,
        days_of_week=days_of_week, weeks_of_month=weeks_of_month,
        months=_parse_months(schedule), repetition=repetition,
    )


def _parse_time(element):
    _check_children(element, _TIME_ALLOWED, "TimeTrigger")
    start, end, enabled, repetition = _parse_common(element)
    return Trigger(
        type="time", start=start, end=end, enabled=enabled, repetition=repetition,
    )


def _parse_settings(root, fields):
    settings = _one(root, "Settings")
    if settings is None:
        return

    policy = _text(settings, "MultipleInstancesPolicy")
    if policy:
        fields["multiple_instances"] = policy

    enabled_text = _text(settings, "Enabled")
    if enabled_text is not None:
        fields["enabled"] = _parse_bool(enabled_text, "Enabled")

    limit_text = _text(settings, "ExecutionTimeLimit")
    if limit_text is not None:
        limit = parse_duration(limit_text)
        # §1：``PT0S`` 等于「不限」，模型里用 ``None`` 表示
        fields["execution_time_limit"] = limit if limit > timedelta(0) else None

    delay_text = _text(settings, "RandomDelay")
    if delay_text is not None:
        fields["random_delay"] = parse_duration(delay_text)


# ------------------------------------------------------------------ 公共 API


def parse_task_xml(text):
    """把任务 XML 解析为 :class:`~wtask.model.Task`。

    所有结构 / 取值问题都抛 :class:`~wtask.errors.TaskDefError`，
    ``kind`` 取值见 ``docs/TASKSCHEMA.md`` §9。
    """
    if not isinstance(text, (str, bytes)):
        raise TaskDefError("xml", "task xml must be str or bytes, got %r" % (type(text),))
    try:
        root = ET.fromstring(text)
    except ET.ParseError as exc:
        raise TaskDefError("xml", str(exc))
    except (ValueError, TypeError) as exc:  # 例如含 NUL 字符的文本
        raise TaskDefError("xml", str(exc))
    if root is None or not isinstance(root.tag, str):
        raise TaskDefError("xml", "task xml has no root element")

    if _tag(root) != "Task":
        raise TaskDefError("schema", "root element must be <Task>, got <%s>" % _tag(root))

    version = (root.get("version") or "").strip()
    if version not in SUPPORTED_VERSIONS:
        raise TaskDefError("version", "unsupported task version: %r" % (root.get("version"),))

    holders = _children(root, "Triggers")
    if not holders:
        raise TaskDefError("structure", "missing <Triggers>")
    if len(holders) > 1:
        raise TaskDefError("schema", "duplicate <Triggers>")

    triggers = []
    for child in holders[0]:
        local = _tag(child)
        if not local:
            continue
        if local == "CalendarTrigger":
            triggers.append(_parse_calendar(child))
        elif local == "TimeTrigger":
            triggers.append(_parse_time(child))
        else:
            # §2：``<Triggers>`` 下只允许 CalendarTrigger / TimeTrigger
            raise TaskDefError("trigger", "unknown trigger element <%s>" % local)
    if not triggers:
        raise TaskDefError("structure", "<Triggers> is empty")

    fields = {"version": version, "triggers": tuple(triggers)}
    _parse_settings(root, fields)

    task = validate_task(Task(**fields))
    return task


def _format_datetime(value):
    return value.strftime(DATETIME_FORMAT)


def _weekday_elements(days):
    return "".join("<%s/>" % WEEKDAY_NAMES[day] for day in sorted(days))


def _month_elements(months):
    return "".join("<%s/>" % MONTH_NAMES[month - 1] for month in sorted(months))


def _schedule_xml(trigger, inner):
    lines = []
    if trigger.type == "daily":
        lines.append(inner + "<ScheduleByDay>")
        lines.append(inner + "  <DaysInterval>%d</DaysInterval>" % trigger.days_interval)
        lines.append(inner + "</ScheduleByDay>")
    elif trigger.type == "weekly":
        lines.append(inner + "<ScheduleByWeek>")
        lines.append(
            inner + "  <DaysOfWeek>" + _weekday_elements(trigger.days_of_week) + "</DaysOfWeek>"
        )
        lines.append(inner + "  <WeeksInterval>%d</WeeksInterval>" % trigger.weeks_interval)
        lines.append(inner + "</ScheduleByWeek>")
    elif trigger.type == "monthly":
        lines.append(inner + "<ScheduleByMonth>")
        lines.append(
            inner
            + "  <DaysOfMonth>"
            + "".join("<Day>%d</Day>" % day for day in sorted(set(trigger.days_of_month)))
            + "</DaysOfMonth>"
        )
        lines.append(inner + "  <Months>" + _month_elements(trigger.months) + "</Months>")
        lines.append(inner + "</ScheduleByMonth>")
    elif trigger.type == "monthly_dow":
        lines.append(inner + "<ScheduleByMonthDayOfWeek>")
        lines.append(
            inner
            + "  <Weeks>"
            + "".join("<Week>%d</Week>" % w for w in sorted(set(trigger.weeks_of_month)))
            + "</Weeks>"
        )
        lines.append(
            inner + "  <DaysOfWeek>" + _weekday_elements(trigger.days_of_week) + "</DaysOfWeek>"
        )
        lines.append(inner + "  <Months>" + _month_elements(trigger.months) + "</Months>")
        lines.append(inner + "</ScheduleByMonthDayOfWeek>")
    elif trigger.type != "time":
        raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))
    return lines


def _trigger_xml(trigger, indent):
    pad = " " * indent
    inner = " " * (indent + 2)
    name = "TimeTrigger" if trigger.type == "time" else "CalendarTrigger"
    # 顺序固定：StartBoundary → EndBoundary → Enabled → 日程 → Repetition（§7）
    lines = [pad + "<%s>" % name]
    lines.append(inner + "<StartBoundary>%s</StartBoundary>" % _format_datetime(trigger.start))
    if trigger.end is not None:
        lines.append(inner + "<EndBoundary>%s</EndBoundary>" % _format_datetime(trigger.end))
    if not trigger.enabled:
        lines.append(inner + "<Enabled>false</Enabled>")

    lines.extend(_schedule_xml(trigger, inner))

    repetition = trigger.repetition
    if repetition is not None:
        lines.append(inner + "<Repetition>")
        lines.append(inner + "  <Interval>%s</Interval>" % format_duration(repetition.interval))
        if repetition.duration is not None:
            lines.append(
                inner + "  <Duration>%s</Duration>" % format_duration(repetition.duration)
            )
        if repetition.stop_at_duration_end:
            lines.append(inner + "  <StopAtDurationEnd>true</StopAtDurationEnd>")
        lines.append(inner + "</Repetition>")

    lines.append(pad + "</%s>" % name)
    return lines


def task_to_xml(task):
    """把 :class:`~wtask.model.Task` 规范化为 XML 文本。

    规范化规则见 ``docs/TASKSCHEMA.md`` §7：元素与属性顺序固定、缺省值省略、
    日期时间写作 ``YYYY-MM-DDTHH:MM:SS``、时长写成规范形式。
    """
    lines = ['<Task version="%s" xmlns="%s">' % (task.version, NS)]
    lines.append("  <Triggers>")
    for trigger in task.triggers:
        lines.extend(_trigger_xml(trigger, 4))
    lines.append("  </Triggers>")
    lines.append("  <Settings>")
    lines.append(
        "    <MultipleInstancesPolicy>%s</MultipleInstancesPolicy>" % task.multiple_instances
    )
    if not task.enabled:
        lines.append("    <Enabled>false</Enabled>")
    if task.execution_time_limit:
        lines.append(
            "    <ExecutionTimeLimit>%s</ExecutionTimeLimit>"
            % format_duration(task.execution_time_limit)
        )
    if task.random_delay:
        lines.append("    <RandomDelay>%s</RandomDelay>" % format_duration(task.random_delay))
    lines.append("  </Settings>")
    lines.append("</Task>")
    return "\n".join(lines) + "\n"

"""wtask.schedule —— 触发时间计算。

本模块只做「给定任务与起始时刻，算出接下来的若干次运行时刻」这件事。
所有计算都在**本地 naive 时间**上进行（不涉及时区与夏令时）。

语义依据 ``docs/TASKSCHEMA.md`` §3 / §4 / §5 / §8。
"""

import calendar
from datetime import datetime, timedelta

from .errors import TaskDefError

#: 主出现扫描的基准跨度（天）。
HORIZON_DAYS = 800

#: 主出现扫描的最大跨度（天）。超出该跨度的任务定义视为不可调度。
#: 取值足够覆盖「一年一次」「四年一次」这类稀疏日程，同时给永不触发的
#: 日程（例如 2 月 30 日）一个确定的终止边界。
MAX_SCAN_DAYS = 3660

#: ``plan_window`` 一次最多枚举多少次运行。
PLAN_HARD_LIMIT = 20000

#: 模型里合法的触发器 ``type``
TRIGGER_TYPES = ("time", "daily", "weekly", "monthly", "monthly_dow")

#: 一次查询里最多展开多少个候选时刻（防止退化配置把枚举撑爆）。
_EXPANSION_BUDGET = 500000

_MICROS_PER_SECOND = 1000000
_MICROS_PER_DAY = 86400 * _MICROS_PER_SECOND

_ZERO = timedelta(0)


# ------------------------------------------------------------------ 日历工具


def _micros(delta):
    """``timedelta`` -> 整数微秒（精确、无浮点误差）。"""
    return (
        delta.days * _MICROS_PER_DAY
        + delta.seconds * _MICROS_PER_SECOND
        + delta.microseconds
    )


def _weekday_index(day):
    """Python 的 ``date.weekday()`` 是 Monday=0..Sunday=6；本模块统一用 Sunday=0。"""
    return (day.weekday() + 1) % 7


def _week_start(day):
    """返回 ``day`` 所在周的周一（周按**周一起始**划分，见 §3.2）。"""
    return day - timedelta(days=day.weekday())


def _week_number(day, anchor):
    """``day`` 与 ``anchor`` 相隔多少个「周一起始」的整周（可为负）。"""
    return (_week_start(day) - _week_start(anchor)).days // 7


def _week_index(day):
    """返回 ``day`` 在本月内的日历周序号（1 起，按日号划分，见 §3.4）。

    1–7 日为第 1 周，8–14 日为第 2 周，15–21 日为第 3 周，
    22–28 日为第 4 周，29 日及以后为第 5 周。
    """
    return (day.day - 1) // 7 + 1


def _weeks_in_month(day):
    """返回 ``day`` 所在月份共有多少个「日历周」（4 或 5）。"""
    days_in_month = calendar.monthrange(day.year, day.month)[1]
    return (days_in_month - 1) // 7 + 1


def _match_week(day, wanted):
    """``<Week>`` 匹配。

    1..4 表示第 n 周；**5 表示该月的最后一周**（在只有 4 个日历周的月份里
    就是第 4 周，例如平年 2 月）。
    """
    index = _week_index(day)
    last = _weeks_in_month(day)
    for week in wanted:
        target = last if week >= 5 else week
        if index == target:
            return True
    return False


def _day_matches(trigger, day):
    """``day`` 这一天是否是这个触发器的一个主出现日（不看时刻）。"""
    kind = trigger.type

    if kind == "daily":
        # §3.1：锚点是 StartBoundary 的日期
        interval = trigger.days_interval
        if interval <= 0:
            raise TaskDefError("range", "DaysInterval out of 1..365: %r" % (interval,))
        return (day - trigger.start.date()).days % interval == 0

    if kind == "weekly":
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        interval = trigger.weeks_interval
        if interval <= 0:
            raise TaskDefError("range", "WeeksInterval out of 1..52: %r" % (interval,))
        # §3.2：StartBoundary 所在周是第 0 周，之后每隔 interval 周
        return _week_number(day, trigger.start.date()) % interval == 0

    if kind == "monthly":
        # §3.3：月份与日号都要命中
        if trigger.months and day.month not in trigger.months:
            return False
        return day.day in trigger.days_of_month

    if kind == "monthly_dow":
        if trigger.months and day.month not in trigger.months:
            return False
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        return _match_week(day, trigger.weeks_of_month)

    if kind == "time":
        return day == trigger.start.date()

    raise TaskDefError("trigger", "unknown trigger type: %r" % (kind,))


# ------------------------------------------------------------------ 出现时刻


def _scan_bounds(trigger, after, horizon_days, hard_stop=None):
    """返回主出现日扫描区间 ``(first, last)``；无候选时返回 ``None``。"""
    start_day = trigger.start.date()
    last = max(after.date(), start_day) + timedelta(days=horizon_days)
    if hard_stop is not None and hard_stop < last:
        last = hard_stop
    if trigger.end is not None and trigger.end.date() < last:
        last = trigger.end.date()
    if last < start_day:
        return None

    repetition = trigger.repetition
    if repetition is None or repetition.interval <= _ZERO:
        # 没有重复：早于 after 当日的主出现不可能产出 > after 的运行
        first = max(start_day, after.date())
    elif repetition.duration is not None:
        # 只有 ``T + Duration > after`` 的主出现才可能产出 after 之后的运行
        lookback = repetition.duration.days + 2
        first = max(start_day, after.date() - timedelta(days=lookback))
    else:
        # 不限时长的重复：任何主出现都可能一直延续到 after 之后
        first = start_day
    if first > last:
        return None
    return first, last


def _primary_occurrences(trigger, after, horizon_days=MAX_SCAN_DAYS, hard_stop=None):
    """惰性产出主出现时刻（升序，可含早于 ``after`` 的，供重复展开使用）。"""
    bounds = _scan_bounds(trigger, after, horizon_days, hard_stop)
    if bounds is None:
        return
    first, last = bounds
    time_of_day = trigger.start.time()
    one_day = timedelta(days=1)
    day = first
    while day <= last:
        if _day_matches(trigger, day):
            moment = datetime.combine(day, time_of_day)
            # §4：主出现必须 >= StartBoundary，且不得超过 EndBoundary
            if moment >= trigger.start:
                if trigger.end is not None and moment > trigger.end:
                    return
                yield moment
        day += one_day


def _expand(trigger, occurrence, after, limit):
    """把一次主出现展开为若干次实际运行（含 ``<Repetition>``，见 §5）。"""
    if limit <= 0:
        return []
    repetition = trigger.repetition
    if repetition is None:
        return [occurrence] if occurrence > after else []

    step = _micros(repetition.interval)
    if step <= 0:
        # 退化配置：按「不重复」处理，避免除零与死循环。
        return [occurrence] if occurrence > after else []

    gap = _micros(after - occurrence)
    if gap < 0:
        first_k = 0
    else:
        # 最小的 k 使得 occurrence + k*Interval 严格晚于 after
        first_k = gap // step + 1

    last_k = None
    duration = repetition.duration
    if duration is not None:
        total = _micros(duration)
        if total <= 0:
            return []
        # §5：只保留 k*Interval < Duration
        last_k = -((-total) // step) - 1
        if last_k < first_k:
            return []
    if trigger.end is not None:
        # §5：重复产生的时刻同样受 EndBoundary 约束
        room = _micros(trigger.end - occurrence)
        if room < 0:
            return []
        cap = room // step
        if last_k is None or cap < last_k:
            last_k = cap
        if last_k < first_k:
            return []

    runs = []
    one_step = timedelta(microseconds=step)
    moment = occurrence + one_step * first_k
    k = first_k
    while len(runs) < limit and (last_k is None or k <= last_k):
        runs.append(moment)
        k += 1
        moment += one_step
    return runs


def _collect(task, after, limit, horizon_days=MAX_SCAN_DAYS, hard_stop=None):
    """收集 ``after`` 之后最早的 ``limit`` 次运行（升序、去重）。"""
    runs = []
    seen = set()
    threshold = None
    budget = _EXPANSION_BUDGET

    for trigger in task.triggers:
        # §8：单个触发器被禁用时跳过该触发器
        if not trigger.enabled:
            continue
        occurrences = _primary_occurrences(trigger, after, horizon_days, hard_stop)
        for occurrence in occurrences:
            # 主出现升序：一旦超过当前第 limit 名的时刻，后面的都无望入选
            if threshold is not None and occurrence > threshold:
                break
            if budget <= 0:
                break
            room = limit if limit < budget else budget
            expanded = _expand(trigger, occurrence, after, room)
            budget -= len(expanded)
            for moment in expanded:
                if moment not in seen:
                    seen.add(moment)
                    runs.append(moment)
            if len(runs) >= limit:
                runs.sort()
                del runs[limit:]
                threshold = runs[-1]

    runs.sort()
    return runs


# ------------------------------------------------------------------ 公共 API


def next_runs(task, after, count):
    """返回 ``after`` 之后最近的 ``count`` 次运行时刻（升序、去重）。

    * 任务被禁用（``task.enabled`` 为假）时返回空列表；
    * 触发器被禁用（``trigger.enabled`` 为假）时跳过该触发器；
    * 返回的时刻**严格大于** ``after``；不足 ``count`` 次时返回实际数量。
    """
    if not task.enabled:
        return []
    if count is None or count <= 0:
        return []
    return _collect(task, after, int(count), MAX_SCAN_DAYS)


def plan_window(task, start, end):
    """返回位于 ``(start, end]`` 区间内的全部运行时刻（升序、去重）。"""
    if not task.enabled:
        return []
    if end < start:
        return []
    return [
        moment
        for moment in _collect(
            task, start, PLAN_HARD_LIMIT, MAX_SCAN_DAYS, hard_stop=end.date()
        )
        if moment <= end
    ]


