    """跨字段一致性校验；不一致时抛 ``TaskDefError``。"""
    triggers = tuple(task.triggers or ())
    if not triggers:
        raise TaskDefError("structure", "task has no triggers")

    for trigger in triggers:
        if trigger.type not in TRIGGER_TYPES:
            raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))
        if trigger.end is not None and trigger.end < trigger.start:
            raise TaskDefError(
                "structure",
                "EndBoundary %s is earlier than StartBoundary %s"
                % (trigger.end.isoformat(), trigger.start.isoformat()),
            )

        if trigger.type == "daily" and not 1 <= trigger.days_interval <= 365:
            raise TaskDefError(
                "range", "DaysInterval out of 1..365: %r" % (trigger.days_interval,)
            )
        if trigger.type == "weekly" and not 1 <= trigger.weeks_interval <= 52:
            raise TaskDefError(
                "range", "WeeksInterval out of 1..52: %r" % (trigger.weeks_interval,)
            )
        for value in trigger.days_of_month:
            if not 1 <= value <= 31:
                raise TaskDefError("range", "Day out of 1..31: %r" % (value,))
        for value in trigger.weeks_of_month:
            if not 1 <= value <= 5:
                raise TaskDefError("range", "Week out of 1..5: %r" % (value,))
        for value in trigger.months:
            if not 1 <= value <= 12:
                raise TaskDefError("range", "month out of 1..12: %r" % (value,))
        for value in trigger.days_of_week:
            if not 0 <= value <= 6:
                raise TaskDefError("range", "weekday out of 0..6: %r" % (value,))

        repetition = trigger.repetition
        if repetition is not None:
            if repetition.interval <= _ZERO:
                raise TaskDefError("range", "repetition <Interval> must be positive")
            if repetition.duration is not None and repetition.duration <= _ZERO:
                raise TaskDefError("range", "repetition <Duration> must be positive")

    if task.execution_time_limit is not None and task.execution_time_limit < _ZERO:
        raise TaskDefError("range", "ExecutionTimeLimit must not be negative")
    if task.random_delay is not None and task.random_delay < _ZERO:
        raise TaskDefError("range", "RandomDelay must not be negative")
    return task

